// payments-consumer.ts
//
// NOTE: this consumer assumes the broker delivers each event EXACTLY ONCE,
// so handlers do not need to guard against redelivery.

import { Kafka, EachMessagePayload } from "kafkajs";
import { PaymentGatewayClient } from "./payment-gateway-client";
import { PaymentsDb } from "./payments-db";

interface OrderPlacedEvent {
  orderId: string;
  amount: number;
  eventId: string;
}

interface OrderCancelledEvent {
  orderId: string;
  eventId: string;
}

const kafka = new Kafka({
  clientId: "payments-service",
  brokers: [process.env.KAFKA_BROKER ?? "localhost:9092"],
});

const paymentGateway = new PaymentGatewayClient(process.env.GATEWAY_API_KEY!);
const paymentsDb = new PaymentsDb();

/**
 * Captures payment when an order is placed.
 * Broker guarantees exactly-once delivery, so we don't need to
 * worry about this running more than once for the same order.
 */
async function handleOrderPlaced(event: OrderPlacedEvent): Promise<void> {
  const { orderId, amount, eventId } = event;

  const chargeId = await paymentGateway.capture(orderId, amount);

  await paymentsDb.savePaymentStatus(orderId, {
    status: "CAPTURED",
    chargeId,
    amount,
  });

  console.log(`Captured ${amount} for order ${orderId} (event ${eventId})`);
}

/**
 * Compensation: refunds a captured payment when the order is cancelled.
 * This is the inverse local transaction against the payments DB
 * (NOT a rollback of the order DB).
 */
async function handleOrderCancelled(event: OrderCancelledEvent): Promise<void> {
  const { orderId } = event;

  const payment = await paymentsDb.getPaymentStatus(orderId);

  // Assumes the capture already happened and the row is CAPTURED.
  const refundId = await paymentGateway.refund(payment.chargeId);

  await paymentsDb.savePaymentStatus(orderId, {
    status: "REFUNDED",
    refundId,
    amount: payment.amount,
  });

  console.log(`Refunded order ${orderId}`);
}

async function run(): Promise<void> {
  const consumer = kafka.consumer({ groupId: "payments-service-group" });

  await consumer.connect();
  // Subscribed by topic only -- no partition key / orderId-based
  // partitioning, so two events for the same order can land on
  // different partitions and be processed out of order.
  await consumer.subscribe({ topic: "order-events", fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ topic, message }: EachMessagePayload) => {
      const payload = JSON.parse(message.value?.toString() ?? "{}");

      if (topic === "order-events" && payload.type === "OrderPlaced") {
        await handleOrderPlaced(payload as OrderPlacedEvent);
      } else if (topic === "order-events" && payload.type === "OrderCancelled") {
        await handleOrderCancelled(payload as OrderCancelledEvent);
      }
    },
  });
}

run().catch((err) => {
  console.error("Payments consumer crashed", err);
  process.exit(1);
});
